class Solution { const int MOD=1000000007;int gcd(int a,int b){while(b){int t=a%b;a=b;b=t;}return a;}public:int distinctSequences(int n){if(n==1)return 6;long long dp[7][7]={};for(int a=1;a<=6;++a)for(int b=1;b<=6;++b)if(a!=b&&gcd(a,b)==1)dp[a][b]=1;for(int length=3;length<=n;++length){long long next[7][7]={};for(int previous=1;previous<=6;++previous)for(int last=1;last<=6;++last)if(dp[previous][last])for(int value=1;value<=6;++value)if(value!=last&&value!=previous&&gcd(last,value)==1)next[last][value]=(next[last][value]+dp[previous][last])%MOD;memcpy(dp,next,sizeof(dp));}long long answer=0;for(auto& row:dp)for(long long value:row)answer=(answer+value)%MOD;return answer;} };
